const SettingsFeature={id:"settings",name:"Settings",icon:"settings",route:!1,render(){const e=NotificationService.isMorningBriefEnabled();return`<div class="fade-in">\n      <div class="top-header"><h1>Settings</h1></div>\n      <div style="padding:16px;">\n\n        <div class="card" style="margin-bottom:16px;">\n          <div style="font-weight:600;margin-bottom:12px;">Your Details</div>\n          <div class="form-group">\n            <label>Name</label>\n            <input type="text" class="input" id="set-name" value="${Utils.escapeAttr(CONFIG.advisorName||"")}" placeholder="Your full name" onblur="SettingsFeature.setName(this.value)">\n          </div>\n          <div class="form-group">\n            <label>Weekly Earnings Target (£)</label>\n            <input type="number" class="input" id="set-target" value="${CONFIG.weeklyTarget||600}" step="10" min="0" onblur="SettingsFeature.setTarget(this.value)">\n            <div class="hint">What you want to take home this week. Everything else derives from this.</div>\n          </div>\n          <div class="form-group" style="margin-bottom:0;">\n            <label>Weekly Sales Target (derived)</label>\n            <input type="text" class="input" id="set-sales-target" value="${Utils.formatCurrency(TaxCalculator.getRequiredWeeklySales(CONFIG.weeklyTarget)).replace(".00","")}" disabled style="opacity:0.75;">\n            <div class="hint">Sales needed to hit your earnings target at the current ${(100*TaxCalculator.getEffectiveCommissionRate()).toFixed(1)}% effective commission rate. Change your commission structure below to update this automatically.</div>\n          </div>\n          <div class="form-group" style="margin-bottom:0;margin-top:14px;">\n            <label>Minimum Hourly Value (&pound;)</label>\n            <input type="number" class="input" id="set-min-hourly" value="${CONFIG.minHourlyRate||""}" placeholder="${TaxCalculator.getMinHourlyRate().rate.toFixed(0)} (estimated)" step="1" min="0" onblur="SettingsFeature.setMinHourlyRate(this.value)">\n            <div class="hint">What your time is worth, at minimum. Only used by "Check my floor" on a visit after a price objection — leave blank to use a rough estimate from your weekly target.</div>\n          </div>\n        </div>\n\n        <div class="card" style="margin-bottom:16px;">\n          <div style="font-weight:600;margin-bottom:12px;">Company Branding</div>\n          <div class="form-group" style="margin-bottom:0;">\n            <label>Company Name</label>\n            <input type="text" class="input" id="set-company-name" value="${Utils.escapeAttr(CONFIG.companyName||"")}" placeholder="e.g. Your Company Ltd" onblur="SettingsFeature.setCompanyName(this.value)">\n            <div class="hint">Shown throughout the app in place of "AdvisorOS". Leave blank to use the default AdvisorOS branding.</div>\n          </div>\n        </div>\n\n        <div class="card" style="margin-bottom:16px;">\n          <div style="font-weight:600;margin-bottom:4px;">Business Base</div>\n          <div style="font-size:12px;color:var(--text-secondary);margin-bottom:12px;">Where you normally start and return from. Used for route distance and ETA planning.</div>\n          <div class="form-group" style="margin-bottom:0;">\n            <label>Home / Business Address</label>\n            <textarea class="textarea" id="set-business-address" placeholder="e.g. 12 Example Street, Manchester M14 7FZ" onblur="SettingsFeature.setBusinessAddress(this.value)">${Utils.escapeHtml(CONFIG.businessAddress||"")}</textarea>\n          </div>\n        </div>\n\n        <div class="card" style="margin-bottom:16px;">\n          <div style="display:flex; align-items:center; justify-content:space-between;">\n            <div>\n              <div style="font-weight:600;">Morning Brief</div>\n              <div style="font-size:12px;color:var(--text-secondary);margin-top:2px;">7am UK time — but only if AdvisorOS is open (or was recently) around then. Phones suspend background tabs/PWAs, so this won't reliably fire overnight; it's a bonus, not a real alarm.</div>\n            </div>\n            <button class="btn btn-sm ${e?"btn-primary":"btn-outline"}" onclick="SettingsFeature.toggleMorningBrief()">\n              ${e?"On":"Off"}\n            </button>\n          </div>\n        </div>\n\n        ${this.renderCommissionCard()}\n\n        <div class="card" style="margin-bottom:16px;">\n          <div style="font-weight:600;margin-bottom:12px;">Advisor Mode</div>\n          <div class="segmented">\n            <button class="segment ${"company"===CONFIG.advisorMode?"active":""}" onclick="SettingsFeature.setMode('company')">Company</button>\n            <button class="segment ${"independent"===CONFIG.advisorMode?"active":""}" onclick="SettingsFeature.setMode('independent')">Independent</button>\n          </div>\n        </div>\n\n        <div class="form-group"><label>Trade</label>\n          <select class="select" onchange="SettingsFeature.setTrade(this.value)">\n            ${CONFIG.trades.map(e=>`<option value="${e.id}" ${CONFIG.trade===e.id?"selected":""}>${e.name}</option>`).join("")}\n          </select>\n        </div>\n\n        <div class="card" style="margin-bottom:16px;">\n          <div style="font-weight:600;margin-bottom:12px;">Units</div>\n          <div style="display:flex;gap:16px;">\n            <div style="flex:1;"><label style="font-size:12px;color:var(--text-secondary);">Distance</label>\n              <div class="segmented" style="margin-top:4px;">\n                <button class="segment ${"miles"===CONFIG.distanceUnit?"active":""}" onclick="SettingsFeature.setDistanceUnit('miles')">mi</button>\n                <button class="segment ${"km"===CONFIG.distanceUnit?"active":""}" onclick="SettingsFeature.setDistanceUnit('km')">km</button>\n              </div>\n              ${"GB"===CONFIG.country?'<div style="font-size:11px;color:var(--text-tertiary);margin-top:4px;">HMRC pays mileage relief in miles</div>':""}\n            </div>\n            <div style="flex:1;"><label style="font-size:12px;color:var(--text-secondary);">Measurement</label>\n              <div class="segmented" style="margin-top:4px;">\n                <button class="segment ${"mm"===CONFIG.measurementUnit?"active":""}" onclick="SettingsFeature.setMeasurementUnit('mm')">mm</button>\n                <button class="segment ${"cm"===CONFIG.measurementUnit?"active":""}" onclick="SettingsFeature.setMeasurementUnit('cm')">cm</button>\n                <button class="segment ${"inches"===CONFIG.measurementUnit?"active":""}" onclick="SettingsFeature.setMeasurementUnit('inches')">in</button>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div class="divider-text">Data</div>\n        ${this.renderStorageCard()}\n        <div style="display:flex;flex-direction:column;gap:8px;">\n          <button class="btn btn-outline btn-sm" onclick="ExportService.exportBackup()"><span class="material-symbols-rounded">backup</span>Export Backup</button>\n          <button class="btn btn-outline btn-sm" onclick="SettingsFeature.importBackup()"><span class="material-symbols-rounded">restore</span>Import Backup</button>\n          <button class="btn btn-outline btn-sm" onclick="SettingsFeature.exportCSV()"><span class="material-symbols-rounded">download</span>Export to CSV</button>\n          <input type="file" id="import-file" accept=".json" style="display:none;" onchange="SettingsFeature.handleImport(event)">\n        </div>\n\n        <div style="margin-top:32px;text-align:center;color:var(--text-tertiary);font-size:13px;">\n          <div>${CONFIG.companyName?Utils.escapeHtml(CONFIG.companyName)+" · ":""}AdvisorOS v5.0</div>\n          <div style="margin-top:4px;">Your day, visits, follow-ups, and money in one place.</div>\n        </div>\n      </div>\n    </div>`},renderStorageCard(){const e=App.state.storageStatus||{},t=e.mode||"checking",s=e.localStorage&&e.database&&"memory"!==t,n=s?"database":"warning",i=s?"Storage looks persistent":"Storage needs attention",a=e.warning||`Using ${t}. Keep using the same website address so your data stays in the same app storage.`,o=e.origin&&"null"!==e.origin?e.origin:window.location.href.split("#")[0];return`\n      <div class="card" style="margin-bottom:16px;border-left:4px solid ${s?"var(--secondary)":"var(--warning)"};">\n        <div style="display:flex;gap:10px;align-items:flex-start;">\n          <span class="material-symbols-rounded" style="color:${s?"var(--secondary)":"var(--warning)"};">${n}</span>\n          <div style="min-width:0;">\n            <div style="font-weight:700;margin-bottom:4px;">${Utils.escapeHtml(i)}</div>\n            <div style="font-size:12px;color:var(--text-secondary);line-height:1.45;">${Utils.escapeHtml(a)}</div>\n            <div style="font-size:11px;color:var(--text-tertiary);line-height:1.35;margin-top:8px;overflow-wrap:anywhere;">${Utils.escapeHtml(o)}</div>\n          </div>\n        </div>\n      </div>\n    `},persist(){const e={advisorName:CONFIG.advisorName,companyName:CONFIG.companyName,businessAddress:CONFIG.businessAddress,businessLatLng:CONFIG.businessLatLng||null,weeklyTarget:CONFIG.weeklyTarget,weeklySalesTarget:CONFIG.weeklySalesTarget,minHourlyRate:CONFIG.minHourlyRate,advisorMode:CONFIG.advisorMode,trade:CONFIG.trade,country:CONFIG.country,currency:CONFIG.currency,taxSystem:CONFIG.taxSystem,dateFormat:CONFIG.dateFormat,distanceUnit:CONFIG.distanceUnit,measurementUnit:CONFIG.measurementUnit,commission:CONFIG.commission,onboardingComplete:!0};localStorage.setItem("advisoros_config",JSON.stringify(e));try{DB.setSetting("config",e)}catch(e){}},renderCommissionCard(){const e=CONFIG.commission||{},t=e.mode||"two_stage",s=1e3,n=TaxCalculator.estimateCommission(s),i=(n/s*100).toFixed(1);return`\n      <div class="card" style="margin-bottom:16px;">\n        <div style="font-weight:600;margin-bottom:4px;">Commission Rate</div>\n        <div style="font-size:12px;color:var(--text-secondary);margin-bottom:12px;">How commission is calculated from a sale's value.</div>\n\n        <div class="segmented" style="margin-bottom:12px;">\n          <button class="segment ${"two_stage"===t?"active":""}" onclick="SettingsFeature.setCommissionMode('two_stage')">Sale reduction + net %</button>\n          <button class="segment ${"simple"===t?"active":""}" onclick="SettingsFeature.setCommissionMode('simple')">Simple %</button>\n        </div>\n\n        ${"two_stage"===t?`\n          <div class="form-group">\n            <label>Step 1: Reduce sale value by (%)</label>\n            <input type="number" class="input" id="set-commission-reduction" value="${e.saleReductionRate??20}" step="0.1" min="0" max="100" onblur="SettingsFeature.setSaleReductionRate(this.value)">\n            <div class="hint">e.g. 20 means the net figure is 80% of the sale value.</div>\n          </div>\n          <div class="form-group" style="margin-bottom:0;">\n            <label>Step 2: Commission on the net (%)</label>\n            <input type="number" class="input" id="set-commission-net" value="${e.netCommissionRate??15.25}" step="0.01" min="0" max="100" onblur="SettingsFeature.setNetCommissionRate(this.value)">\n            <div class="hint">Applied to the net figure from Step 1.</div>\n          </div>\n        `:`\n          <div class="form-group" style="margin-bottom:0;">\n            <label>Commission Rate (%)</label>\n            <input type="number" class="input" id="set-commission-simple" value="${e.simpleRate??10}" step="0.1" min="0" max="100" onblur="SettingsFeature.setSimpleCommissionRate(this.value)">\n            <div class="hint">Applied directly to the full sale value.</div>\n          </div>\n        `}\n\n        <div class="inset-dark" style="margin-top:12px;padding:10px 12px;background:var(--bg);border-radius:8px;font-size:12px;color:var(--text-secondary);">\n          Example: on a ${Utils.formatCurrency(s)} sale, commission is ${Utils.formatCurrency(n)} (${i}% effective).\n        </div>\n      </div>\n    `},refreshInPlace(){const e=document.getElementById("main");if(!e)return;const t=e.scrollTop;e.innerHTML=this.render(),e.scrollTop=t},setCommissionMode(e){CONFIG.commission={...CONFIG.commission||{},mode:e},this.persist(),this.refreshInPlace()},setSaleReductionRate(e){const t=parseFloat(e);if(!Number.isFinite(t)||t<0||t>100)return Toast.show("Enter a percentage between 0 and 100","error"),void this.refreshInPlace();CONFIG.commission={...CONFIG.commission||{},saleReductionRate:t},this.persist(),Toast.show("Commission rate updated","success"),this.refreshInPlace()},setNetCommissionRate(e){const t=parseFloat(e);if(!Number.isFinite(t)||t<0||t>100)return Toast.show("Enter a percentage between 0 and 100","error"),void this.refreshInPlace();CONFIG.commission={...CONFIG.commission||{},netCommissionRate:t},this.persist(),Toast.show("Commission rate updated","success"),this.refreshInPlace()},setSimpleCommissionRate(e){const t=parseFloat(e);if(!Number.isFinite(t)||t<0||t>100)return Toast.show("Enter a percentage between 0 and 100","error"),void this.refreshInPlace();CONFIG.commission={...CONFIG.commission||{},simpleRate:t},this.persist(),Toast.show("Commission rate updated","success"),this.refreshInPlace()},setCompanyName(e){CONFIG.companyName=e.trim(),this.persist(),App.setBranding?.(),Toast.show("Company name updated","success")},setBusinessAddress(e){const t=e.trim();t!==(CONFIG.businessAddress||"")&&(CONFIG.businessLatLng=null),CONFIG.businessAddress=t,this.persist(),Toast.show("Business base updated","success")},setName(e){CONFIG.advisorName=e.trim(),this.persist(),Toast.show("Name updated","success")},setTarget(e){const t=parseFloat(e);!t||t<=0?Toast.show("Please enter a valid target","error"):(CONFIG.weeklyTarget=t,this.persist(),Toast.show("Weekly target updated","success"),this.refreshInPlace())},setMinHourlyRate(e){if(""===e||null==e)return CONFIG.minHourlyRate=null,this.persist(),Toast.show("Using an estimated hourly value instead","info"),void this.refreshInPlace();const t=parseFloat(e);!t||t<=0?Toast.show("Please enter a valid hourly rate","error"):(CONFIG.minHourlyRate=t,this.persist(),Toast.show("Minimum hourly value updated","success"),this.refreshInPlace())},async toggleMorningBrief(){if(NotificationService.isMorningBriefEnabled())NotificationService.disableMorningBrief(),Toast.show("Morning brief turned off","info");else{await NotificationService.scheduleMorningBrief()?Toast.show("Morning brief queued for 7am when app is active","success"):Toast.show("Notification permission denied","error")}this.refreshInPlace()},async setMode(e){CONFIG.advisorMode=e,this.persist(),Toast.show(`Switched to ${e} mode`,"success"),this.refreshInPlace()},async setTrade(e){CONFIG.trade=e,this.persist()},async setDistanceUnit(e){CONFIG.distanceUnit=e,this.persist(),this.refreshInPlace()},async setMeasurementUnit(e){CONFIG.measurementUnit=e,this.persist(),this.refreshInPlace()},importBackup(){document.getElementById("import-file").click()},async handleImport(e){const t=e.target.files[0];if(t)try{await ExportService.importBackup(t),Toast.show("Data imported","success")}catch(e){Toast.show("Import failed: "+e.message,"error")}},exportCSV(){ExportService.exportCSV("appointments"),ExportService.exportCSV("expenses"),ExportService.exportCSV("trips")}};App.registerFeature(SettingsFeature);